    let mut score = bin_residual as f64;

    // Apply time decay
    let time_decay = (step_index as f64 / total_items as f64).powf(2.0);
    score -= time_decay * 15.0; // Increased penalty to favor earlier packing

    // Adjust score based on bin capacity
    if bin_capacity > 100 {
        score *= 0.80 + ((bin_residual as f64) / bin_capacity as f64) * 0.20;
    } else {
        score *= 0.75 + ((bin_residual as f64) / bin_capacity as f64) * 0.25; // Slightly reduced bonus for smaller bins
    }

    // Lookahead pairing bonus
    if bin_residual == next_item_size && next_item_size > 0 {
        score -= 60.0; // Increased penalty to favor better lookahead matches
    }

    // Penalty for empty bin
    if bin_residual == 0 {
        score -= 50.0; // Stronger penalty to avoid creating empty bins
    }

    // Favor placing items closer to the end of the horizon
    let horizon_factor = 1.0 - (step_index as f64 / total_items as f64);
    if step_index < total_items / 3 {
        score += 25.0 * horizon_factor; // Increased bonus to favor earlier packing with a diminishing return
    } else if step_index < total_items / 2 {
        score += 15.0 * horizon_factor; // Moderate bonus for mid-time horizon items
    }

    // Adjust score based on bin residual
    score = score * 0.70 + ((bin_residual as f64) as f64) * 0.30;

    // Introduce non-linear conditionals
    if bin_residual < mean_residual / 2 {
        score -= 10.0; // Penalty for bins with significantly lower residual than the average
    } else if bin_residual > mean_residual * 2 {
        score += 15.0; // Bonus for bins with significantly higher residual than the average
    }

    score
}

